#include <bits/stdc++.h>
using namespace std;
const int MAXN=510;
typedef pair<int,int> Pair;
#define p make_pair
#define f first
#define s second

int n, m, mod, C[MAXN][MAXN];
Pair dp[MAXN][MAXN];

int sumRange(int l, int r) {
    return (l + r) * (r - l + 1) / 2;
}

int addMod(int a, int b) {
    int res=a+b;
    if(res>=mod) res-=mod;
    return res;
}

Pair operator+(const Pair &a, const Pair &b) {
    return p(addMod(a.f, b.f), addMod(a.s, b.s));
}

Pair operator*(const Pair &a, const Pair &b) {
    long long fi=1LL*a.f*b.f%mod;
    long long se=(1LL*a.f*b.s+1LL*a.s*b.f)%mod;
    return p((int)fi, (int)se);
}

int main() {
#ifdef LOCAL
    freopen("a.in","r",stdin);
    freopen("a.out","w",stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin>>n>>m>>mod;
    for(int i=0;i<MAXN;i++) {
        C[i][0]=1;
        for(int j=1;j<=i;j++) C[i][j]=addMod(C[i-1][j], C[i-1][j-1]);
    }
    for(int i=0;i<=n;i++) {
        dp[i][0]=p(1,0);
        for(int j=1;j<=i && j<=m;j++) {
            if(i!=j) {
                for(int k=1;k<=i;k++)
                    dp[i][j]=dp[i][j]+dp[k-1][k-1]*dp[i-k][j-k+1]*p(C[j][k-1],0);
            } else {
                for(int k=1;k<=i;k++) {
                    auto t1=dp[k-1][k-1];
                    auto t2=dp[i-k][i-k];
                    auto combi=p(C[i-1][k-1],0);
                    int fct= i+1 - sumRange(1,k) + sumRange(k+1,i) - k*(i-k);
                    auto fctp=p(fct,0);
                    dp[i][j]=dp[i][j]+t1*t2*combi*fctp;
                }
            }
        }
    }
    cout<<dp[n][m].s;
    return 0;
}
